{"test_code":"from stats.buckets import bucket_of, histogram


def test_bucket_of_large_value() -> None:
    assert bucket_of(100000000000000015, 10) == 100000000000000010


def test_bucket_of_large_negative_truncates_toward_zero() -> None:
    assert bucket_of(-100000000000000015, 10) == -100000000000000010


def test_histogram_large_values() -> None:
    assert histogram([100000000000000015], 10) == {100000000000000010: 1}
","rationale":"bucket_of uses float division, so large ints lose precision; the test asserts exact integer bucket starts for large positive and negative values and via histogram."}
